template <typename UnionPtrType>
NetworkTypePropertiesPtr NetworkTypeProperties::Clone() const {
  switch (tag_) {
    case Tag::kCellular:
      return NewCellular(
          mojo::Clone(*data_.cellular));
    case Tag::kEthernet:
      return NewEthernet(
          mojo::Clone(*data_.ethernet));
    case Tag::kWifi:
      return NewWifi(
          mojo::Clone(*data_.wifi));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, NetworkTypeProperties>::value>::type*>
bool NetworkTypeProperties::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kCellular:
      return mojo::Equals(*(data_.cellular), *(other.data_.cellular));
    case Tag::kEthernet:
      return mojo::Equals(*(data_.ethernet), *(other.data_.ethernet));
    case Tag::kWifi:
      return mojo::Equals(*(data_.wifi), *(other.data_.wifi));
  }

  return false;
}
